changeSet.sql:
INSERT INTO modules (name, code, enabled) SELECT 'General', 'GENERAL', TRUE WHERE NOT EXISTS (SELECT 1 FROM modules WHERE code = 'GENERAL');
INSERT INTO sub_modules (name, code, module_id, enabled, is_sellable, read_only_capable) SELECT seed.name, seed.code, general.id, TRUE, seed.is_sellable, seed.read_only_capable FROM ( SELECT 'Historia clínica' AS name, 'CLINICAL_HISTORY' AS code, TRUE AS is_sellable, TRUE AS read_only_capable UNION ALL SELECT 'Agenda', 'AGENDA', TRUE, TRUE UNION ALL SELECT 'Vacunación', 'VACCINATION', TRUE, TRUE UNION ALL SELECT 'Hospitalización', 'HOSPITALIZATION', TRUE, TRUE UNION ALL SELECT 'Laboratorio', 'LABORATORY', TRUE, TRUE UNION ALL SELECT 'Imagen diagnóstica', 'DIAGNOSTIC_IMAGING', TRUE, TRUE UNION ALL SELECT 'Desparasitación', 'DEWORMING', TRUE, TRUE UNION ALL SELECT 'Cirugía', 'SURGERY', TRUE, TRUE UNION ALL SELECT 'Spa', 'SPA', TRUE, TRUE UNION ALL SELECT 'Guardería', 'DAYCARE', TRUE, TRUE UNION ALL SELECT 'Sucursales', 'BRANCH', FALSE, TRUE UNION ALL SELECT 'Empresa', 'COMPANY', FALSE, TRUE UNION ALL SELECT 'Empleados', 'EMPLOYEES', FALSE, TRUE UNION ALL SELECT 'Roles y permisos', 'ROLES', FALSE, TRUE UNION ALL SELECT 'Medicamentos', 'MEDICAMENTS', FALSE, TRUE UNION ALL SELECT 'Inventario', 'INVENTORY', TRUE, TRUE UNION ALL SELECT 'Caja', 'CASH', TRUE, TRUE UNION ALL SELECT 'Servicios', 'SERVICES', TRUE, TRUE UNION ALL SELECT 'Promociones', 'PROMOTIONS', TRUE, TRUE UNION ALL SELECT 'Impuestos', 'TAXES', TRUE, TRUE UNION ALL SELECT 'Cuentas por cobrar', 'OPEN_ACCOUNTS', TRUE, TRUE UNION ALL SELECT 'Facturación electrónica', 'BILLING', TRUE, TRUE UNION ALL SELECT 'Compras', 'PURCHASES', TRUE, TRUE UNION ALL SELECT 'Derechos de suscripción', 'ENTITLEMENT', FALSE, TRUE UNION ALL SELECT 'Suscripciones', 'SUBSCRIPTION', FALSE, TRUE UNION ALL SELECT 'Cotizaciones de suscripción', 'QUOTE', FALSE, TRUE UNION ALL SELECT 'Cobros de suscripción', 'SUBSCRIPTION_BILLING', FALSE, TRUE UNION ALL SELECT 'Pagos de suscripción', 'SUBSCRIPTION_PAYMENT', FALSE, TRUE UNION ALL SELECT 'Cobranza de suscripción', 'DUNNING', FALSE, TRUE ) seed JOIN modules general ON general.code = 'GENERAL' LEFT JOIN sub_modules existing ON existing.code = seed.code WHERE existing.id IS NULL;
UPDATE sub_modules SET is_sellable = CASE code WHEN 'CLINICAL_HISTORY' THEN TRUE WHEN 'AGENDA' THEN TRUE WHEN 'VACCINATION' THEN TRUE WHEN 'HOSPITALIZATION' THEN TRUE WHEN 'LABORATORY' THEN TRUE WHEN 'DIAGNOSTIC_IMAGING' THEN TRUE WHEN 'DEWORMING' THEN TRUE WHEN 'SURGERY' THEN TRUE WHEN 'SPA' THEN TRUE WHEN 'DAYCARE' THEN TRUE WHEN 'INVENTORY' THEN TRUE WHEN 'CASH' THEN TRUE WHEN 'SERVICES' THEN TRUE WHEN 'PROMOTIONS' THEN TRUE WHEN 'TAXES' THEN TRUE WHEN 'OPEN_ACCOUNTS' THEN TRUE WHEN 'BILLING' THEN TRUE WHEN 'PURCHASES' THEN TRUE ELSE FALSE END, read_only_capable = TRUE WHERE code IN ( 'CLINICAL_HISTORY', 'AGENDA', 'VACCINATION', 'HOSPITALIZATION', 'LABORATORY', 'DIAGNOSTIC_IMAGING', 'DEWORMING', 'SURGERY', 'SPA', 'DAYCARE', 'BRANCH', 'COMPANY', 'EMPLOYEES', 'ROLES', 'MEDICAMENTS', 'INVENTORY', 'CASH', 'SERVICES', 'PROMOTIONS', 'TAXES', 'OPEN_ACCOUNTS', 'BILLING', 'PURCHASES', 'ENTITLEMENT', 'SUBSCRIPTION', 'QUOTE', 'SUBSCRIPTION_BILLING', 'SUBSCRIPTION_PAYMENT', 'DUNNING' );
